await dataSource.transaction(async (em) => {
  const lock = await em.createQueryBuilder(LockRecord, "l")
    .setLock("pessimistic_write")
    .where("l.lockable = :key", { key })
    .getOne();
  if (lock && lock.owner !== sessionId) throw new LockedError(lock.owner);
  if (!lock) {
    await em.insert(LockRecord, { lockable: key, owner: sessionId });
  }
});
